// FindAgenda retrieves a single record by ID with an executor.
// If selectCols is empty Find will return all columns.
func FindAgenda(ctx context.Context, exec boil.ContextExecutor, ageID int, selectCols ...string) (*Agenda, error) {
	agendaObj := &Agenda{}

	sel := "*"
	if len(selectCols) > 0 {
		sel = strings.Join(strmangle.IdentQuoteSlice(dialect.LQ, dialect.RQ, selectCols), ",")
	}
	query := fmt.Sprintf(
		"select %s from `agenda` where `age_id`=?", sel,
	)

	q := queries.Raw(query, ageID)

	err := q.Bind(ctx, exec, agendaObj)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, sql.ErrNoRows
		}
		return nil, errors.Wrap(err, "models: unable to select from agenda")
	}

	if err = agendaObj.doAfterSelectHooks(ctx, exec); err != nil {
		return agendaObj, err
	}

	return agendaObj, nil
}

